/* ---------- tour callouts ---------- */
function callout(x, y, str, anchor, lx1, ly1, lx2, ly2) {
  var gr = layerAnno.group();
  gr.line(lx1, ly1, lx2, ly2).stroke({ color: '#555', width: 1.2 });
  gr.circle(5).center(lx2, ly2).fill('#555');
  ptLabel(gr, x, y, str, { size: 15, fill: '#222', anchor: anchor, halo: true, haloW: 4 });
  gr.hide();
  return gr;
}
var callCation = callout(200, 140, 'charge = group number', 'start', 196, 136, 120, 178);
var callAnion = callout(1010, 140, 'charge = group number − 18', 'end', 1016, 136, 1090, 178);
var callNoble = callout(1150, 60, 'Group 18: full shell → no ion', 'end', 1156, 56, 1250, 96);
var callD = callout(600, 150, 'd-block: two or more charges — position alone fails', 'middle', 600, 160, 600, 320);

/* ---------- state ---------- */
var scheme = 'type', tour = 0, curGroup = 1, bandOn = false, step = 0;

function paintCells() {
  for (var i = 0; i < cells.length; i++) {
    var c = cells[i], f;
    if (scheme === 'charge') {
      if (c.cat === 'dblock' || c.cat === 'lanth' || c.cat === 'act') f = hatch;
      else if (c.q === null || c.q === undefined) f = '#f5f5f5';
      else f = CH_FILL[String(c.q)] || '#f5f5f5';
    } else f = CAT_FILL[c.cat];
    c.rect.fill(f);
  }
}

function relevant(c) {
  if (tour === 0) return true;
  if (c.fblock) return false;
  if (tour === 1) return c.g === 1 || c.g === 2 || c.g === 13;
  if (tour === 2) return c.g >= 15 && c.g <= 17;
  if (tour === 3) return c.g === 18;
  if (tour === 4) return c.g >= 3 && c.g <= 12;
  return true;
}

function applyTour() {
  for (var i = 0; i < cells.length; i++) cells[i].node.attr('opacity', relevant(cells[i]) ? 1 : 0.18);
  layerLink.attr('opacity', tour === 0 ? 1 : 0.18);
  callCation.hide(); callAnion.hide(); callNoble.hide(); callD.hide();
  if (tour === 1) callCation.show();
  if (tour === 2) callAnion.show();
  if (tour === 3) callNoble.show();
  if (tour === 4) callD.show();
  for (var t = 0; t < 5; t++) {
    var b = document.getElementById('tourBtn' + t);
    if (b) b.className = (t === tour) ? 'active' : '';
  }
}

var GROUP_TEXT = {
  1: 'Group 1 — alkali metals lose 1 e⁻ → charge +1 (Li⁺, Na⁺, K⁺ …)',
  2: 'Group 2 — alkaline earths lose 2 e⁻ → charge +2 (Mg²⁺, Ca²⁺ …)',
  13: 'Group 13 — lose 3 e⁻ → charge +3 (Al³⁺)',
  14: 'Group 14 — 14 − 18 = −4 (C⁴⁻); mostly forms covalent bonds instead',
  15: 'Group 15 — gain 3 e⁻: 15 − 18 = −3 (N³⁻, P³⁻, As³⁻)',
  16: 'Group 16 — gain 2 e⁻: 16 − 18 = −2 (O²⁻, S²⁻, Se²⁻, Te²⁻)',
  17: 'Group 17 — gain 1 e⁻: 17 − 18 = −1 (F⁻, Cl⁻, Br⁻, I⁻)',
  18: 'Group 18 — noble gases already have a full shell: no ion'
};
function groupText(g) {
  if (GROUP_TEXT[g]) return GROUP_TEXT[g];
  return 'Group ' + g + ' — transition metals: charge is variable, so position alone cannot predict it';
}

function drawBand() {
  if (!bandOn) { band.hide(); bandCap.hide(); document.getElementById('groupHint').textContent = ''; return; }
  band.show(); bandCap.show();
  band.x(colX(curGroup) - 5);  band.y(86);
  band.height(rowY(7) + CH - 86 + 6);
  bandCap.node.textContent = groupText(curGroup);
  var cx = colX(curGroup) + CW / 2;
  bandCap.attr('x', Math.min(1080, Math.max(220, cx)));
  document.getElementById('groupHint').textContent = groupText(curGroup);
}

/* ---------- selection / info ---------- */
function selectCell(c) {
  selRing.move(c.x - 4, c.y - 4).size(c.w + 8, c.h + 8);
  var box = document.getElementById('infoBox');
  if (c.lab) {
    var L = c.lab;
    box.innerHTML = '<b>' + L.L[0][0] + ' — ' + L.n + '</b><br>Group ' + c.g + ' · Period ' + c.p +
      '<br>Atom: ' + L.cfg + '<br>Ion: ' + L.ion + '<br><span style="color:#555">' + L.why + '</span>';
    showPopup(L.n + ' (' + L.L[0][0] + ')',
      'Neutral atom: ' + L.cfg + '. Ion: ' + L.ion + '. ' + L.why);
  } else {
    var where = c.fblock ? (c.cat === 'lanth' ? 'Lanthanide series' : 'Actinide series')
      : ('Group ' + c.g + ' · Period ' + c.p);
    box.innerHTML = '<b>' + where + '</b><br><span style="color:#555">' + CATNAME[c.cat] + '</span>';
    showPopup(where, CATNAME[c.cat] + '. This cell carries no charge label in the figure: either the element rarely forms a simple monatomic ion, or its charge is not fixed by its column.');
  }
}

/* ---------- legend ---------- */
function sw(color, label, hatched) {
  var bg = hatched ? 'repeating-linear-gradient(45deg,#f3e7cd,#f3e7cd 3px,#c09550 3px,#c09550 4.5px)' : color;
  return '<span style="display:inline-block;width:12px;height:12px;border:1px solid #999;border-radius:2px;background:' +
    bg + ';vertical-align:-2px;margin-right:4px"></span>' + label + '<br>';
}
function updateLegend() {
  var el = document.getElementById('legendBox');
  if (scheme === 'type') {
    el.innerHTML = '<b>Legend — element type</b><br>' +
      sw(CAT_FILL.alkali, 'Group 1 alkali metals (+1)') +
      sw(CAT_FILL.alkaline, 'Group 2 alkaline earths (+2)') +
      sw(CAT_FILL.dblock, 'Transition metals (variable)') +
      sw(CAT_FILL.nonmetal, 'Nonmetals (−3, −2)') +
      sw(CAT_FILL.halogen, 'Halogens (−1)') +
      sw(CAT_FILL.noble, 'Noble gases (no ion)') +
      sw(CAT_FILL.blank, 'Other main-group / metalloid');
  } else {
    el.innerHTML = '<b>Legend — ion charge</b><br>' +
      sw(CH_FILL['3'], '+3') + sw(CH_FILL['2'], '+2') + sw(CH_FILL['1'], '+1') +
      sw(CH_FILL['0'], '0 (noble gas)') +
      sw(CH_FILL['-1'], '−1') + sw(CH_FILL['-2'], '−2') + sw(CH_FILL['-3'], '−3') + sw(CH_FILL['-4'], '−4') +
      sw('', 'variable (d-block)', true) +
      sw('#f5f5f5', 'no simple ion');
  }
}

