/* ---------- cells ---------- */
var cells = [];
function makeCell(x, y, w, h, cat, meta) {
  var g = layerCells.group();
  var r = g.rect(w, h).move(x, y).radius(4)
    .fill(CAT_FILL[cat]).stroke({ color: meta && meta.fblock ? '#7f7f7f' : '#9aa0a6', width: meta && meta.fblock ? 1.6 : 1.1 });
  r.node.style.transition = 'fill .3s';
  g.node.style.transition = 'opacity .25s';
  var c = { node: g, rect: r, cat: cat, x: x, y: y, w: w, h: h };
  for (var k in meta) c[k] = meta[k];
  cells.push(c);
  g.css('cursor', 'pointer');
  g.on('mousemove', function (e) { showTooltip(cellTip(c), e); });
  g.on('mouseleave', hideTooltip);
  g.on('click', function () { selectCell(c); });
  return c;
}

function cellTip(c) {
  if (c.lab) return c.lab.n + ' — ' + (c.lab.q === 0 ? 'no ion' : 'forms ' + c.lab.ion.split(' ')[0]) + '  (click for details)';
  if (c.fblock) return (c.cat === 'lanth' ? 'Lanthanide' : 'Actinide') + ' series — f-block';
  return CATNAME[c.cat] + (c.g ? ' · Group ' + c.g + ', Period ' + c.p : '');
}

for (var p = 1; p <= 7; p++) {
  for (var g = 1; g <= 18; g++) {
    var cat = catOf(p, g);
    if (cat === 'none') continue;
    var key = p + '_' + g;
    var lab = LAB[key] || null;
    var c = makeCell(colX(g), rowY(p), CW, CH, cat, { p: p, g: g, lab: lab, q: lab ? lab.q : null });
    if (lab) {
      var cy = rowY(p) + CH / 2;
      if (lab.L.length === 1) {
        drawIon(c.node, colX(g) + CW / 2, cy + 6, lab.L[0], 17);
      } else {
        drawIon(c.node, colX(g) + CW / 2, cy - 4, lab.L[0], 15);
        drawIon(c.node, colX(g) + CW / 2, cy + 17, lab.L[1], 15);
      }
    }
  }
}

function drawIon(parent, x, y, L, size) {
  var parts = [{ t: L[0] }];
  if (L[2]) parts.push({ t: L[2], size: size * 0.62, dy: size * 0.24 });
  if (L[1]) parts.push({ t: L[1], size: size * 0.68, dy: L[2] ? -size * 0.6 : -size * 0.34 });
  return ptText(parent, x, y, parts, { size: size });
}

