  { t: 'Groups 15–17: charge = group − 18', n: 'Nonmetals gain electrons instead. Group 17 gains one for −1, Group 16 gains two for −2, Group 15 gains three for −3 — exactly how far they sit left of the noble gases.', s: { color: false, tour: 2, grp: 17, band: true } },
  { t: 'Why? The noble-gas target', n: 'Group 18 carries no charge label because it already has a full valence shell. Every cation and anion in the table is an atom moving toward the nearest noble-gas configuration.', s: { color: false, tour: 3, grp: 18, band: true } },
  { t: 'Where the rule breaks: the d-block', n: 'Transition metals show two or more charges — Cr³⁺ and Cr⁶⁺, Fe²⁺ and Fe³⁺, Cu⁺ and Cu²⁺ — because d electrons are removed at similar energies. Group position alone cannot predict their charge.', s: { color: false, tour: 4, grp: 8, band: true } },
  { t: 'Two ways to classify the same table', n: 'Recolor by charge value instead of element family: the cation/anion split lands almost exactly on the metal/nonmetal boundary, while the d-block becomes a striped region of ambiguity.', s: { color: true, tour: 0, grp: 8, band: true } }
];

function applyStep(i) {
  step = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  var st = STEPS[step].s;
  var gi = document.getElementById('groupSweepInput');
  gi.value = st.grp;
  document.getElementById('groupSweepVal').value = st.grp;
  curGroup = st.grp;
  bandOn = st.band;
  var ci = document.getElementById('colorSchemeInput');
  ci.checked = st.color;
  scheme = st.color ? 'charge' : 'type';
  tour = st.tour;
  paintCells();
  updateLegend();
  applyTour();
  drawBand();
  document.getElementById('demoNarration').innerHTML = '<b>' + STEPS[step].t + '</b><br>' + STEPS[step].n;
  document.getElementById('stepLabel').textContent = (step + 1) + ' / ' + STEPS.length;
}
function nextStep() { applyStep(step + 1); }
function prevStep() { applyStep(step - 1); }

/* ---------- init ---------- */
document.getElementById('infoBox').innerHTML =
  '<b>Click any cell</b><br><span style="color:#555">See the atom\'s electron configuration, the ion it forms, and why that charge follows from its column.</span>';
applyStep(0);
window.__markRendered();
