    var ts = document.createElementNS(NSU, 'tspan');
    ts.textContent = p.t;
    if (p.size) ts.setAttribute('font-size', p.size);
    if (p.dy) ts.setAttribute('dy', p.dy);
    t.appendChild(ts);
  }
  parent.node.appendChild(t);
  return SVG(t);
}
function ptLabel(parent, x, y, s, opt) { return ptText(parent, x, y, [{ t: s }], opt); }

