function catOf(p, g) {
  if (p === 1) return g === 1 ? 'h' : (g === 18 ? 'noble' : 'none');
  if (g === 1) return 'alkali';
  if (g === 2) return 'alkaline';
  if (g >= 3 && g <= 12) {
