function makeCell(x, y, w, h, cat, meta) {
  var g = layerCells.group();
  var r = g.rect(w, h).move(x, y).radius(4)
    .fill(CAT_FILL[cat]).stroke({ color: meta && meta.fblock ? '#7f7f7f' : '#9aa0a6', width: meta && meta.fblock ? 1.6 : 1.2 });
  r.node.style.transition = 'fill .3s';
  g.node.style.transition = 'opacity .25s';
  var c = { node: g, rect: r, cat: cat, x: x, y: y, w: w, h: h };
  for (var k in meta) c[k] = meta[k];
  cells.push(c);
  g.css('cursor', 'pointer');
  g.on('mousemove', function (e) { showTooltip(cellTip(c), e); });
  g.on('mouseleave', hideTooltip);
  g.on('click', function () { selectCell(c); });
  return c;
}
function cellTip(c) {
  if (c.lab) {
    var ion = c.lab.q === 0 ? 'no ion' : 'forms ' + c.lab.L.map(function (L) { return L[0] + (L[2] || '') + L[1]; }).join(' / ');
    return c.lab.n + ' — ' + ion + '  (click for details)';
  }
  if (c.fblock) return (c.cat === 'lanth' ? 'Lanthanide' : 'Actinide') + ' series — f-block';
  return CATNAME[c.cat] + (c.g ? ' · Group ' + c.g + ', Period ' + c.p : '');
}

function drawIon(parent, x, y, L, size) {
