  if (L[2]) parts.push({ t: L[2], size: size * 0.6, dy: size * 0.26 });
  if (L[1]) parts.push({ t: L[1], size: size * 0.66, dy: L[2] ? -size * 0.58 : -size * 0.36 });
  return ptText(parent, x, y, parts, { size: size });
}

