for (var pp = 1; pp <= 7; pp++) ptLabel(layerBase, 30, rowY(pp) + CH / 2 + 8, String(pp), { size: 21, fill: '#7030a0' });
function gnum(gv, y) { ptLabel(layerBase, colX(gv) + CW / 2, y, String(gv), { size: 21, fill: '#2a6ef0' }); }
gnum(1, Y0 - 12); gnum(18, Y0 - 12);
gnum(2, rowY(2) - 12);
for (var gg = 13; gg <= 17; gg++) gnum(gg, rowY(2) - 12);
for (var gd = 3; gd <= 12; gd++) gnum(gd, rowY(4) - 12);

/* ---------- red box + curved arrow to f-block ---------- */
layerLink.rect(CW + 8, (rowY(7) + CH) - rowY(6) + 8).move(colX(3) - 4, rowY(6) - 4)
  .fill('none').stroke({ color: '#e8402a', width: 2.6 });
var ARROW = 'M' + (colX(3) + CW / 2 - 40) + ',' + (GRIDB + 6) + ' C158,700 176,730 222,742';
layerLink.path(ARROW).fill('none').stroke({ color: '#c9c9c9', width: 12, linecap: 'round' });
layerLink.path(ARROW).fill('none').stroke({ color: '#e8402a', width: 2.3, linecap: 'round' });
layerLink.polygon('240,750 218,752 222.8,736').fill('#f2b8ad').stroke({ color: '#e8402a', width: 2, linejoin: 'round' });
layerLink.node.style.transition = 'opacity .25s';

/* ---------- selection ring ---------- */
var selRing = layerAnno.rect(CW + 8, CH + 8).move(-999, -999).radius(6).fill('none').stroke({ color: '#111', width: 2.8 });

/* ---------- group band ---------- */
var band = layerBand.rect(CW + 10, 100).move(colX(1) - 5, 112).fill({ color: '#ffe24d', opacity: 0.32 })
  .stroke({ color: '#e0a800', width: 1.8 }).radius(5).hide();
band.node.style.pointerEvents = 'none';
var bandCap = ptLabel(layerBand, GRIDC, GRIDB + 26, '', { size: 21, fill: '#8a6a00', halo: true, haloW: 5 });
bandCap.hide();

/* ---------- tour callouts ---------- */
function callout(x, y, str, anchor, lx1, ly1, lx2, ly2) {
  var gr = layerAnno.group();
  gr.line(lx1, ly1, lx2, ly2).stroke({ color: '#555', width: 1.4 });
  gr.circle(6).center(lx2, ly2).fill('#555');
  ptLabel(gr, x, y, str, { size: 22, fill: '#222', anchor: anchor, halo: true, haloW: 5 });
  gr.hide();
  return gr;
}
var callCation = callout(152, 168, 'charge = group number', 'start', 148, 164, 92, 200);
var callAnion = callout(1010, 168, 'charge = group number − 18', 'end', 1016, 164, 1110, 196);
var callNoble = callout(1140, 168, 'full shell → no ion', 'end', 1146, 164, 1252, 178);
var callD = callout(528, 268, 'd-block: two or more charges — position alone fails', 'middle', 528, 280, 528, 344);

/* ---------- state ---------- */
var scheme = 'type', tour = 0, curGroup = 1, bandOn = false, step = 0;

function paintCells() {
  for (var i = 0; i < cells.length; i++) {
    var c = cells[i], f;
    if (scheme === 'charge') {
      if (c.cat === 'dblock' || c.cat === 'lanth' || c.cat === 'act') f = hatch;
      else if (c.q === null || c.q === undefined) f = '#f5f5f5';
      else f = CH_FILL[String(c.q)] || '#f5f5f5';
    } else f = CAT_FILL[c.cat];
    c.rect.fill(f);
  }
}

function relevant(c) {
  if (tour === 0) return true;
  if (c.fblock) return false;
  if (tour === 1) return c.g === 1 || c.g === 2 || c.g === 13;
  if (tour === 2) return c.g >= 15 && c.g <= 17;
  if (tour === 3) return c.g === 18;
  if (tour === 4) return c.g >= 3 && c.g <= 12;
  return true;
}
function applyTour() {
  for (var i = 0; i < cells.length; i++) cells[i].node.attr('opacity', relevant(cells[i]) ? 1 : 0.18);
  layerLink.attr('opacity', tour === 0 ? 1 : 0.18);
  callCation.hide(); callAnion.hide(); callNoble.hide(); callD.hide();
  if (tour === 1) callCation.show();
  if (tour === 2) callAnion.show();
  if (tour === 3) callNoble.show();
  if (tour === 4) callD.show();
  for (var t = 0; t < 5; t++) {
    var b = document.getElementById('tourBtn' + t);
    if (b) b.className = (t === tour) ? 'active' : '';
  }
}

var GROUP_TEXT = {
  1: 'Group 1 — lose 1 e⁻ → +1 (Li⁺, Na⁺, K⁺ …)',
  2: 'Group 2 — lose 2 e⁻ → +2 (Mg²⁺, Ca²⁺ …)',
  13: 'Group 13 — lose 3 e⁻ → +3 (Al³⁺)',
  14: 'Group 14 — 14 − 18 = −4 (C⁴⁻); usually bonds covalently',
  15: 'Group 15 — gain 3 e⁻: 15 − 18 = −3 (N³⁻, P³⁻, As³⁻)',
  16: 'Group 16 — gain 2 e⁻: 16 − 18 = −2 (O²⁻, S²⁻, Se²⁻, Te²⁻)',
  17: 'Group 17 — gain 1 e⁻: 17 − 18 = −1 (F⁻, Cl⁻, Br⁻, I⁻)',
  18: 'Group 18 — noble gases: full shell, no ion'
};
function groupText(gv) {
  return GROUP_TEXT[gv] || ('Group ' + gv + ' — transition metals: charge is variable, so position alone cannot predict it');
}
function drawBand() {
  if (!bandOn) { band.hide(); bandCap.hide(); document.getElementById('groupHint').textContent = ''; return; }
  band.show(); bandCap.show();
  band.x(colX(curGroup) - 5).y(112).height(GRIDB - 112 + 6);
  bandCap.node.textContent = groupText(curGroup);
  bandCap.attr('x', Math.min(1000, Math.max(300, colX(curGroup) + CW / 2)));
  document.getElementById('groupHint').textContent = groupText(curGroup);
}

/* ---------- selection / compact readout ---------- */
function ruleLine(c) {
  var L = c.lab;
  if (!L) return '';
  if (L.q === 'var') return 'd-block: several charges — no single noble-gas target';
  if (L.q === 0) return 'full valence shell → forms no ion';
  if (L.q > 0) return 'loses ' + L.q + ' e⁻  (charge = group ' + c.g + ')';
  return 'gains ' + (-L.q) + ' e⁻  (charge = ' + c.g + ' − 18 = ' + L.q + ')';
}
function selectCell(c) {
  selRing.move(c.x - 4, c.y - 4).size(c.w + 8, c.h + 8);
  var box = document.getElementById('infoBox');
  if (c.lab) {
    var L = c.lab;
    var ions = L.L.map(function (a) { return a[0] + (a[2] || '') + (a[1] ? a[1] : ''); }).join(' / ');
    box.innerHTML = '<b>' + L.L[0][0] + '</b> ' + L.n + ' → <b>' + ions + '</b><br>' +
      L.cfg + ' → ' + L.core + '<br><span style="color:#555">' + ruleLine(c) + '</span>';
    showPopup(L.n.charAt(0).toUpperCase() + L.n.slice(1) + ' (' + L.L[0][0] + ')',
      'Neutral atom: ' + L.cfg + '. Ion core: ' + L.core + '. ' + L.why);
  } else {
    var where = c.fblock ? (c.cat === 'lanth' ? 'Lanthanide series' : 'Actinide series')
      : ('Group ' + c.g + ' · Period ' + c.p);
    box.innerHTML = '<b>' + where + '</b><br><span style="color:#555">' + CATNAME[c.cat] + '</span>';
    showPopup(where, CATNAME[c.cat] + '. This cell carries no charge label: either the element rarely forms a simple monatomic ion, or its charge is not fixed by its column.');
  }
}

/* ---------- compact in-figure legend ---------- */
var LEG_TYPE = [
  [CAT_FILL.alkali, 'alkali +1'], [CAT_FILL.alkaline, 'alkaline earth +2'],
  [CAT_FILL.dblock, 'transition (variable)'], [CAT_FILL.nonmetal, 'nonmetal anions'],
  [CAT_FILL.halogen, 'halogen −1'], [CAT_FILL.noble, 'noble gas (no ion)']
];
var LEG_CHG = [
  [CH_FILL['3'], '+3'], [CH_FILL['2'], '+2'], [CH_FILL['1'], '+1'], [CH_FILL['0'], '0'],
  [CH_FILL['-1'], '−1'], [CH_FILL['-2'], '−2'], [CH_FILL['-3'], '−3'], [CH_FILL['-4'], '−4'],
  [hatch, 'variable (d-block)'], ['#f5f5f5', 'no simple ion']
];
function drawLegend() {
  layerLegend.clear();
  var items = (scheme === 'charge') ? LEG_CHG : LEG_TYPE;
  var pitch = (scheme === 'charge') ? 122 : 205;
  var x = (scheme === 'charge') ? 60 : 90, y = 840;
  for (var i = 0; i < items.length; i++) {
    var cx = x + i * pitch;
    layerLegend.rect(20, 20).move(cx, y - 15).radius(3).fill(items[i][0]).stroke({ color: '#999', width: 1 });
    ptLabel(layerLegend, cx + 26, y + 2, items[i][1], { size: 19, anchor: 'start', fill: '#555', weight: 'normal' });
  }
}

/* ---------- controls ---------- */
function update_groupSweep(v) { curGroup = v; bandOn = true; drawBand(); }
function toggle_colorScheme(on) { scheme = on ? 'charge' : 'type'; paintCells(); drawLegend(); }
function setTour(i) { tour = i; applyTour(); }
function resetFig() { applyStep(0); }

/* ---------- demo steps ---------- */
var STEPS = [
  { t: 'The table as a charge map', n: 'Colored by element family, each cell carries the ion that element most commonly forms. Notice that whole columns share one charge.', s: { color: false, tour: 0, grp: 1, band: false } },
  { t: 'Groups 1 and 2: charge = group number', n: 'Alkali metals lose one electron to give +1; alkaline earths lose two to give +2. Aluminium in Group 13 extends the pattern to +3.', s: { color: false, tour: 1, grp: 2, band: true } },
  { t: 'Groups 15–17: charge = group − 18', n: 'Nonmetals gain electrons instead: Group 17 gains one for −1, Group 16 two for −2, Group 15 three for −3 — exactly how far they sit left of the noble gases.', s: { color: false, tour: 2, grp: 17, band: true } },
  { t: 'Why? The noble-gas target', n: 'Group 18 carries no charge label: its valence shell is already full. Every cation and anion here is an atom moving toward the nearest noble-gas configuration.', s: { color: false, tour: 3, grp: 18, band: true } },
  { t: 'Where the rule breaks: the d-block', n: 'Transition metals show two or more charges — Cr³⁺/Cr⁶⁺, Fe²⁺/Fe³⁺, Cu⁺/Cu²⁺ — because d electrons come off at similar energies. Tick "color by ion charge" to see the d-block become a striped region of ambiguity.', s: { color: false, tour: 4, grp: 8, band: true } }
];
function applyStep(i) {
  step = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  var st = STEPS[step].s;
  document.getElementById('groupSweepInput').value = st.grp;
  document.getElementById('groupSweepVal').value = st.grp;
  curGroup = st.grp; bandOn = st.band;
  document.getElementById('colorSchemeInput').checked = st.color;
  scheme = st.color ? 'charge' : 'type';
  tour = st.tour;
  paintCells(); drawLegend(); applyTour(); drawBand();
  document.getElementById('demoNarration').innerHTML = '<b>' + STEPS[step].t + '</b><br>' + STEPS[step].n;
  document.getElementById('stepLabel').textContent = (step + 1) + ' / ' + STEPS.length;
}
function nextStep() { applyStep(step + 1); }
function prevStep() { applyStep(step - 1); }

/* ---------- init ---------- */
document.getElementById('infoBox').innerHTML =
  '<b>Click any cell</b><br><span style="color:#555">Atom configuration → ion core, and the column rule behind it.</span>';
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: An element's position in the periodic table predicts the charge of the ion it forms: main-group metals lose electrons to reach the preceding noble-gas configuration (charge = group number), nonmetals gain electrons (charge = group number − 18), and transition metals break the rule by forming several different charges.
KEY INSIGHT (what students should walk away understanding): Ionic charge isn't memorized element by element — it's read off the column: every atom gains or loses the fewest electrons needed to match the nearest noble gas, which is why charge equals the group number for metals and group-number-minus-18 for nonmetals, and why the d-block, with no single nearby noble gas, refuses to obey.
DEMO STEPS: 5 guided steps — implement the step player in #ui

