// @FIGURE_CODE_BEGIN
var VW = 1306, VH = 916;
var PTdraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
PTdraw.viewbox(0, 0, VW, VH).attr('preserveAspectRatio', 'xMidYMid meet');

var NSU = 'http://www.w3.org/2000/svg';
var X0 = 46, PITCHX = 70, CW = 63, Y0 = 132, PITCHY = 72, CH = 63;
function colX(g) { return X0 + (g - 1) * PITCHX; }
function rowY(p) { return Y0 + (p - 1) * PITCHY; }
var GRIDR = colX(18) + CW, GRIDC = (X0 + GRIDR) / 2, GRIDB = rowY(7) + CH;

/* ---------- text helper ---------- */
function ptText(parent, x, y, parts, opt) {
  opt = opt || {};
  var t = document.createElementNS(NSU, 'text');
  t.setAttribute('x', x); t.setAttribute('y', y);
  t.setAttribute('text-anchor', opt.anchor || 'middle');
  t.setAttribute('font-family', 'Helvetica,Arial,sans-serif');
  t.setAttribute('font-size', opt.size || 20);
  t.setAttribute('font-weight', opt.weight || 'bold');
  t.setAttribute('fill', opt.fill || '#111');
  if (opt.halo) {
    t.setAttribute('paint-order', 'stroke');
    t.setAttribute('stroke', '#fff');
    t.setAttribute('stroke-width', opt.haloW || 5);
    t.setAttribute('stroke-linejoin', 'round');
  }
  if (opt.rotate) t.setAttribute('transform', 'rotate(' + opt.rotate + ',' + x + ',' + y + ')');
  for (var i = 0; i < parts.length; i++) {
    var p = parts[i];
    var ts = document.createElementNS(NSU, 'tspan');
    ts.textContent = p.t;
    if (p.size) ts.setAttribute('font-size', p.size);
    if (p.dy) ts.setAttribute('dy', p.dy);
    t.appendChild(ts);
  }
  parent.node.appendChild(t);
  return SVG(t);
}
function ptLabel(parent, x, y, s, opt) { return ptText(parent, x, y, [{ t: s }], opt); }

/* ---------- layers ---------- */
var layerBase = PTdraw.group();
var layerCells = PTdraw.group();
var layerLink = PTdraw.group();
var layerBand = PTdraw.group();
var layerLegend = PTdraw.group();
var layerAnno = PTdraw.group();

/* ---------- colours ---------- */
var CAT_FILL = {
  h: '#ecedf2', alkali: '#e6d9f4', alkaline: '#dbead0', dblock: '#f6eccb',
  nonmetal: '#e8c2bb', halogen: '#dcdff5', noble: '#bdf4f4', blank: '#ffffff',
  lanth: '#d7ecdd', act: '#f6d8ee'
};
var CH_FILL = {
  '-4': '#5b8ac9', '-3': '#7ba7d9', '-2': '#a6c6e8', '-1': '#cfe0f4',
  '0': '#dedede', '1': '#f9cfc0', '2': '#f0a48d', '3': '#e07a60'
};
var hatch = PTdraw.pattern(9, 9, function (add) {
  add.rect(9, 9).fill('#f3e7cd');
  add.line(0, 9, 9, 0).stroke({ color: '#c09550', width: 1.4 });
