/* ---------- category by position ---------- */
function catOf(p, g) {
  if (p === 1) return g === 1 ? 'h' : (g === 18 ? 'noble' : 'none');
  if (g === 1) return 'alkali';
  if (g === 2) return 'alkaline';
  if (g >= 3 && g <= 12) {
    if (p < 4) return 'none';
    if (p === 6 && g === 3) return 'lanth';
    if (p === 7 && g === 3) return 'act';
    if (p === 7 && g >= 9 && g <= 11) return 'blank';
    return 'dblock';
  }
  if (g === 18) return p <= 6 ? 'noble' : 'blank';
  if (g === 17) return p <= 6 ? 'halogen' : 'blank';
  if (g === 15) return (p >= 2 && p <= 5) ? 'nonmetal' : 'blank';   /* Bi (period 6) stays white */
  if (g === 16) return (p >= 2 && p <= 6) ? 'nonmetal' : 'blank';   /* Po (period 6) salmon */
  return 'blank';
}

