  for (var i = 0; i < items.length; i++) {
    var w = chip + gapIn + items[i][1].length * fs * 0.55;
    ws.push(w);
    var r = rows.length - 1;
    if (rw[r] > 0 && rw[r] + gapOut + w > maxW) { rows.push([]); rw.push(0); r++; }
    rw[r] += (rw[r] > 0 ? gapOut : 0) + w;
    rows[r].push(i);
  }
  for (var r2 = 0; r2 < rows.length; r2++) {
    var x = (VW - rw[r2]) / 2, yy = 866 + r2 * 34;
    for (var j = 0; j < rows[r2].length; j++) {
      var idx = rows[r2][j];
      layerLegend.rect(chip, chip).move(x, yy - chip + 4).radius(3)
        .fill(items[idx][0]).stroke({ color: '#999', width: 1 });
      ptLabel(layerLegend, x + chip + gapIn, yy, items[idx][1], { size: fs, anchor: 'start', fill: '#555', weight: 'normal' });
      x += ws[idx] + gapOut;
    }
  }
}

